export interface Session {
  startTime: number;
  endTime: number;
  duration: number; // in seconds
}

export interface Subtask {
  id: string;
  title: string;
  isCompleted: boolean;
  percentage?: number; // 0-100 granular progress
  timeSpent?: number; // Seconds spent on this subtask
  sessions?: Session[];
}

export interface Task {
  id: string;
  title: string;
  description: string;
  percentage: number; // 0-100
  isCompleted: boolean;
  subtasks: Subtask[];
  createdAt: number;
  totalTimeSpent?: number; // Total seconds spent on this task
}

export type SortOption = 'newest' | 'oldest' | 'progress';

import React, { useState, useEffect, useMemo } from 'react';
import { Task, SortOption } from './types';
import CircularProgress from './components/CircularProgress';
import TaskCard from './components/TaskCard';
import TimerOverlay from './components/TimerOverlay';
import AnalyticsModal from './components/AnalyticsModal';
import { 
  Plus, 
  LayoutGrid, 
  Search, 
  Target, 
  Filter, 
  CheckCircle, 
  ListTodo, 
  Sun, 
  Moon,
  Clock,
  BarChart3,
  ChevronRight
} from 'lucide-react';

const INITIAL_TASKS: Task[] = [
  {
    id: '1',
    title: 'Dashboard Design',
    description: 'Personal tracker mockups.',
    percentage: 85,
    isCompleted: false,
    subtasks: [
      { id: 's1', title: 'User research', isCompleted: true, percentage: 100, timeSpent: 1200 },
      { id: 's2', title: 'Wireframes', isCompleted: true, percentage: 100, timeSpent: 1800 },
      { id: 's3', title: 'Visual identity', isCompleted: false, percentage: 55, timeSpent: 600 },
    ],
    createdAt: Date.now() - 86400000 * 2,
    totalTimeSpent: 3600
  },
  {
    id: '2',
    title: 'React Animation',
    description: 'Build interactions.',
    percentage: 50,
    isCompleted: false,
    subtasks: [
      { id: 's4', title: 'Transitions', isCompleted: true, percentage: 100, timeSpent: 1000 },
      { id: 's5', title: 'Hover states', isCompleted: false, percentage: 0, timeSpent: 800 },
    ],
    createdAt: Date.now() - 86400000,
    totalTimeSpent: 1800
  }
];

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('ascend_tasks_timer_v3');
    return saved ? JSON.parse(saved) : INITIAL_TASKS;
  });
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('ascend_theme');
    return saved === null ? true : saved === 'dark';
  });
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('newest');
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTask, setNewTask] = useState({ title: '', description: '' });

  const [activeTimer, setActiveTimer] = useState<{ taskId: string; subtaskTitle: string } | null>(null);
  const [showAnalytics, setShowAnalytics] = useState(false);

  useEffect(() => {
    localStorage.setItem('ascend_tasks_timer_v3', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    localStorage.setItem('ascend_theme', darkMode ? 'dark' : 'light');
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const formatTimeFull = (seconds: number) => {
    if (seconds === 0) return '0m';
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
  };

  const stats = useMemo(() => {
    if (tasks.length === 0) return { overall: 0, total: 0, completed: 0, subtasks: 0, subtasksCompleted: 0, totalTime: 0, taskBreakdown: [] };
    const totalPercentage = tasks.reduce((acc, task) => acc + task.percentage, 0);
    const subtasks = tasks.flatMap(t => t.subtasks);
    const totalTime = tasks.reduce((acc, t) => acc + (t.totalTimeSpent || 0), 0);

    // Sort tasks by time spent for the breakdown
    const taskBreakdown = [...tasks]
      .filter(t => (t.totalTimeSpent || 0) > 0)
      .sort((a, b) => (b.totalTimeSpent || 0) - (a.totalTimeSpent || 0));

    return {
      overall: totalPercentage / tasks.length,
      total: tasks.length,
      completed: tasks.filter(t => t.isCompleted).length,
      subtasks: subtasks.length,
      subtasksCompleted: subtasks.filter(s => s.isCompleted).length,
      totalTime,
      taskBreakdown
    };
  }, [tasks]);

  const filteredAndSortedTasks = useMemo(() => {
    let result = tasks.filter(t => 
      t.title.toLowerCase().includes(search.toLowerCase())
    );

    result.sort((a, b) => {
      if (sortBy === 'newest') return b.createdAt - a.createdAt;
      if (sortBy === 'oldest') return a.createdAt - b.createdAt;
      if (sortBy === 'progress') return b.percentage - a.percentage;
      return 0;
    });

    return result;
  }, [tasks, search, sortBy]);

  const addTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTask.title.trim()) return;
    const task: Task = {
      id: crypto.randomUUID(),
      title: newTask.title,
      description: newTask.description,
      percentage: 0,
      isCompleted: false,
      subtasks: [],
      createdAt: Date.now(),
      totalTimeSpent: 0
    };
    setTasks([task, ...tasks]);
    setNewTask({ title: '', description: '' });
    setShowAddModal(false);
  };

  const updateTask = (updatedTask: Task) => {
    setTasks(tasks.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const recordTime = (elapsed: number) => {
    if (!activeTimer) return;
    setTasks(tasks.map(t => {
      if (t.id === activeTimer.taskId) {
        const updatedSubtasks = t.subtasks.map(s => {
          if (s.title === activeTimer.subtaskTitle) {
            const endTime = Date.now();
            const startTime = endTime - (elapsed * 1000);
            const newSession = { startTime, endTime, duration: elapsed };
            return { 
              ...s, 
              timeSpent: (s.timeSpent || 0) + elapsed,
              sessions: [...(s.sessions || []), newSession]
            };
          }
          return s;
        });
        return { 
          ...t, 
          subtasks: updatedSubtasks,
          totalTimeSpent: (t.totalTimeSpent || 0) + elapsed 
        };
      }
      return t;
    }));
    setActiveTimer(null);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-slate-100' : 'bg-[#fcfdfe] text-slate-900'} overflow-x-hidden`}>
      <header className={`border-b sticky top-0 z-30 px-6 py-2.5 transition-colors ${darkMode ? 'bg-slate-900/80 border-slate-800' : 'bg-white/80 border-slate-200'} backdrop-blur-md`}>
        <div className="max-w-[1600px] mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <Target size={16} strokeWidth={2.5} />
            </div>
            <h1 className="text-base font-black tracking-tight ">TrackIt</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative group hidden sm:block">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={12} />
              <input
                type="text"
                placeholder="Search focus..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className={`pl-8 pr-3 py-1 border-none rounded-lg text-xs font-medium focus:ring-1 focus:ring-indigo-500 outline-none w-40 transition-all ${darkMode ? 'bg-slate-800 text-slate-200' : 'bg-slate-100 text-slate-700'}`}
              />
            </div>

            <button 
              onClick={() => setDarkMode(!darkMode)}
              className={`p-2 rounded-lg transition-colors ${darkMode ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
              {darkMode ? <Sun size={14} /> : <Moon size={14} />}
            </button>

            <button 
              onClick={() => setShowAddModal(true)}
              className="bg-indigo-600 text-white px-3.5 py-1.5 rounded-lg font-bold text-[11px] uppercase tracking-wider hover:bg-indigo-700 transition-all flex items-center gap-1 shadow-indigo-100 dark:shadow-none shadow-lg"
            >
              <Plus size={14} /> New
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-6 py-6">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          <aside className="lg:col-span-3 space-y-4">
            <div className={`p-6 rounded-2xl border shadow-sm flex flex-col items-center transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
              <h2 className={`text-[10px] font-black uppercase tracking-[0.2em] mb-4 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Focus Score</h2>
              <CircularProgress percentage={stats.overall} size={150} strokeWidth={12} darkMode={darkMode} />

              <div className="mt-8 grid grid-cols-1 gap-2 w-full">
                <div className={`flex justify-between items-center p-3 rounded-xl transition-colors ${darkMode ? 'bg-slate-800/50' : 'bg-slate-50'}`}>
                  <div className="flex items-center gap-2">
                    <ListTodo size={14} className={darkMode ? 'text-slate-500' : 'text-slate-400'} />
                    <span className={`text-[10px] font-black uppercase tracking-wider ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>Active</span>
                  </div>
                  <span className={`text-sm font-black ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>{stats.total}</span>
                </div>
                <div className={`flex justify-between items-center p-3 rounded-xl transition-colors ${darkMode ? 'bg-emerald-950/30' : 'bg-emerald-50'}`}>
                  <div className="flex items-center gap-2">
                    <CheckCircle size={14} className="text-emerald-500" />
                    <span className={`text-[10px] font-black uppercase tracking-wider ${darkMode ? 'text-emerald-400' : 'text-emerald-600'}`}>Completed</span>
                  </div>
                  <span className={`text-sm font-black ${darkMode ? 'text-emerald-400' : 'text-emerald-800'}`}>{stats.completed}</span>
                </div>
              </div>
            </div>

            <div 
              onClick={() => setShowAnalytics(true)}
              className={`p-5 rounded-2xl border shadow-sm transition-all duration-300 group cursor-pointer hover:shadow-md hover:scale-[1.02] ${darkMode ? 'bg-slate-900 border-slate-800 hover:border-indigo-500/30' : 'bg-white border-slate-100 hover:border-indigo-200'}`}
            >
              <div className="flex items-center justify-between mb-5">
                <div className="flex items-center gap-2">
                  <BarChart3 size={14} className="text-indigo-500 group-hover:text-indigo-400 transition-colors" />
                  <h2 className={`text-[10px] font-black uppercase tracking-[0.2em] group-hover:text-indigo-500 transition-colors ${darkMode ? 'text-slate-400' : 'text-slate-600'}`}>Time Analysis</h2>
                </div>
                <ChevronRight size={14} className={`opacity-0 -translate-x-2 group-hover:opacity-100 group-hover:translate-x-0 transition-all ${darkMode ? 'text-indigo-400' : 'text-indigo-600'}`} />
              </div>
              <div className="mb-6 pb-4 border-b border-slate-800/20 dark:border-slate-800">
                <div className="flex items-baseline gap-1.5 mb-1">
                  <span className={`text-3xl font-light tracking-tighter ${darkMode ? 'text-white' : 'text-slate-800'}`}>
                    {formatTimeFull(stats.totalTime)}
                  </span>
                  <span className={`text-[10px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Total Focus</span>
                </div>
              </div>

              <div className="space-y-3">
                <h3 className={`text-[9px] font-black uppercase tracking-[0.1em] ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>Task Breakdown</h3>
                {stats.taskBreakdown.length > 0 ? (
                  <div className="space-y-2 max-h-[300px] overflow-y-auto pr-1">
                    {stats.taskBreakdown.map(task => (
                      <div key={task.id} className="flex flex-col gap-1 group/item">
                        <div className="flex justify-between items-center">
                          <span className={`text-[11px] font-medium truncate max-w-[140px] ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>
                            {task.title}
                          </span>
                          <span className={`text-[10px] font-black tabular-nums ${darkMode ? 'text-indigo-400' : 'text-indigo-600'}`}>
                            {formatTimeFull(task.totalTimeSpent || 0)}
                          </span>
                        </div>
                        <div className={`h-1 w-full rounded-full overflow-hidden ${darkMode ? 'bg-slate-800' : 'bg-slate-100'}`}>
                          <div 
                            className="h-full bg-indigo-500/60 rounded-full transition-all duration-500"
                            style={{ width: `${Math.min(100, ((task.totalTimeSpent || 0) / stats.totalTime) * 100)}%` }}
                          />
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className={`py-6 flex flex-col items-center justify-center rounded-xl border border-dashed ${darkMode ? 'bg-slate-800/20 border-slate-800' : 'bg-slate-50 border-slate-200'}`}>
                    <Clock size={16} className={`mb-1.5 opacity-20 ${darkMode ? 'text-white' : 'text-slate-400'}`} />
                    <p className={`text-[8px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-700' : 'text-slate-400'}`}>No activity logged</p>
                  </div>
                )}
              </div>
            </div>
          </aside>

          <div className="lg:col-span-9">
            <div className="flex items-center justify-between mb-4 px-1">
              <div className="flex items-center gap-2">
                <LayoutGrid size={14} className="text-indigo-500" />
                <h2 className={`text-[11px] font-black uppercase tracking-[0.15em] ${darkMode ? 'text-slate-400' : 'text-slate-800'}`}>Pipeline</h2>
              </div>
              <div className="flex items-center gap-3">
                <div className={`flex items-center gap-1.5 px-2 py-1 border rounded-md shadow-sm transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
                  <Filter size={11} className="text-slate-500" />
                  <select 
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value as SortOption)}
                    className={`bg-transparent text-[10px] font-black uppercase tracking-tighter outline-none cursor-pointer ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}
                  >
                    <option value="newest" className={darkMode ? 'bg-slate-900' : ''}>Newest</option>
                    <option value="oldest" className={darkMode ? 'bg-slate-900' : ''}>Oldest</option>
                    <option value="progress" className={darkMode ? 'bg-slate-900' : ''}>Progress</option>
                  </select>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-3 items-start">
              {filteredAndSortedTasks.length > 0 ? (
                filteredAndSortedTasks.map(task => (
                  <TaskCard 
                    key={task.id} 
                    task={task} 
                    onUpdate={updateTask}
                    onDelete={deleteTask}
                    onStartTimer={(taskId, subtaskTitle) => setActiveTimer({ taskId, subtaskTitle })}
                    darkMode={darkMode}
                  />
                ))
              ) : (
                <div className={`col-span-full py-20 flex flex-col items-center justify-center rounded-2xl border border-dashed shadow-sm transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
                  <Target size={24} strokeWidth={1} className={`mb-3 ${darkMode ? 'text-slate-800' : 'text-slate-200'}`} />
                  <p className={`text-[10px] font-black uppercase tracking-[0.2em] ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>Pipeline Empty</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>

      {activeTimer && (
        <TimerOverlay 
          subtaskTitle={activeTimer.subtaskTitle}
          darkMode={darkMode}
          onClose={() => setActiveTimer(null)}
          onComplete={recordTime}
        />
      )}

      <AnalyticsModal 
        isOpen={showAnalytics}
        onClose={() => setShowAnalytics(false)}
        tasks={tasks}
        darkMode={darkMode}
      />

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/20 dark:bg-black/40 backdrop-blur-[2px] animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <div className="p-6">
              <h2 className={`text-sm font-black uppercase tracking-wider mb-5 ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>Create Task</h2>
              <form onSubmit={addTask} className="space-y-4">
                <div className="space-y-1">
                  <label className={`text-[10px] font-black uppercase tracking-widest ml-1 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Title</label>
                  <input
                    autoFocus required type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                    className={`w-full px-3 py-2 border rounded-xl text-xs font-semibold outline-none focus:ring-1 focus:ring-indigo-500 transition-colors ${darkMode ? 'bg-slate-800 border-slate-700 text-slate-100' : 'bg-slate-50 border-slate-100 text-slate-900'}`}
                    placeholder="Enter goal name..."
                  />
                </div>
                <div className="flex gap-2 pt-3">
                  <button type="button" onClick={() => setShowAddModal(false)} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-50 hover:text-slate-400' : 'text-slate-400 hover:text-slate-500'}`}>Cancel</button>
                  <button type="submit" className="flex-1 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-100 dark:shadow-none">Create</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { Task } from '../types';
import { X, Calendar, Activity } from 'lucide-react';

interface AnalyticsModalProps {
  isOpen: boolean;
  onClose: () => void;
  tasks: Task[];
  darkMode: boolean;
}

interface TimelineSegment {
  taskTitle: string;
  subtaskTitle: string;
  startTime: number;
  endTime: number;
  duration: number;
  color: string;
}

const COLORS = [
  'bg-indigo-500',
  'bg-emerald-500',
  'bg-violet-500',
  'bg-blue-500',
  'bg-rose-500',
  'bg-amber-500',
  'bg-cyan-500',
  'bg-fuchsia-500',
  'bg-lime-500',
  'bg-pink-500'
];

const AnalyticsModal: React.FC<AnalyticsModalProps> = ({ isOpen, onClose, tasks, darkMode }) => {
  if (!isOpen) return null;

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const startOfDay = today.getTime();
  const endOfDay = startOfDay + 24 * 60 * 60 * 1000;

  // Format current date
  const dateStr = today.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

  // Process data for the timeline
  const timelineData = useMemo(() => {
    const segments: TimelineSegment[] = [];
    const taskColors: Record<string, string> = {};
    let colorIndex = 0;

    tasks.forEach(task => {
      // Assign color to task if not already
      if (!taskColors[task.id]) {
        taskColors[task.id] = COLORS[colorIndex % COLORS.length];
        colorIndex++;
      }

      task.subtasks.forEach(subtask => {
        if (subtask.sessions) {
          subtask.sessions.forEach(session => {
            // Filter for sessions that overlap with "Today"
            if (session.startTime >= startOfDay && session.startTime < endOfDay) {
              segments.push({
                taskTitle: task.title,
                subtaskTitle: subtask.title,
                startTime: session.startTime,
                endTime: session.endTime,
                duration: session.duration,
                color: taskColors[task.id]
              });
            }
          });
        }
      });
    });

    return { segments, taskColors };
  }, [tasks, startOfDay, endOfDay]);

  // Aggregated durations for the legend
  const taskAggregates = useMemo(() => {
    const agg: Record<string, { title: string, duration: number, color: string }> = {};
    timelineData.segments.forEach(seg => {
      if (!agg[seg.taskTitle]) {
        agg[seg.taskTitle] = { title: seg.taskTitle, duration: 0, color: seg.color };
      }
      agg[seg.taskTitle].duration += seg.duration;
    });
    return Object.values(agg).sort((a, b) => b.duration - a.duration);
  }, [timelineData]);

  const formatTime = (ts: number) => {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const formatDuration = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div 
        className={`w-full max-w-4xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-300 ${
          darkMode ? 'bg-slate-950 text-slate-100 border border-slate-800' : 'bg-white text-slate-900 border border-slate-200'
        }`}
      >
        {/* Header */}
        <div className={`p-6 border-b flex items-center justify-between ${darkMode ? 'border-slate-800' : 'border-slate-100'}`}>
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Activity size={16} className="text-indigo-500" />
              <h2 className={`text-xs font-black uppercase tracking-widest ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>
                Focus Analysis
              </h2>
            </div>
            <div className="flex items-center gap-2">
              <h1 className="text-xl font-bold tracking-tight">24-Hour Timeline</h1>
              <div className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wide flex items-center gap-1.5 ${darkMode ? 'bg-slate-800 text-slate-300' : 'bg-slate-100 text-slate-600'}`}>
                <Calendar size={10} />
                {dateStr}
              </div>
            </div>
          </div>
          <button 
            onClick={onClose}
            className={`p-2 rounded-full transition-colors ${darkMode ? 'hover:bg-slate-800 text-slate-400 hover:text-white' : 'hover:bg-slate-100 text-slate-400 hover:text-slate-900'}`}
          >
            <X size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="p-8 overflow-y-auto custom-scrollbar flex-1">
          {/* Timeline Chart Container */}
          <div className="mb-12">
            <div className="relative h-24 w-full select-none">
              {/* Grid Lines & Labels */}
              <div className="absolute inset-0 flex justify-between items-end pb-8 pointer-events-none">
                {[0, 4, 8, 12, 16, 20, 24].map((hour) => (
                  <div key={hour} className="flex flex-col items-center h-full justify-end" style={{ width: '1px' }}>
                     <div className={`h-full w-px border-l border-dashed opacity-10 ${darkMode ? 'border-slate-100' : 'border-slate-900'}`} />
                     <span className={`text-[9px] font-bold mt-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>
                       {hour.toString().padStart(2, '0')}:00
                     </span>
                  </div>
                ))}
              </div>

              {/* Main Track */}
              <div className={`absolute left-0 right-0 top-1/2 -translate-y-1/2 h-8 rounded-lg overflow-hidden ${darkMode ? 'bg-slate-900' : 'bg-slate-100'}`}>
                {timelineData.segments.map((segment, idx) => {
                  const daySeconds = 24 * 60 * 60;
                  // Calculate position based on start time relative to start of day
                  const startOffset = (segment.startTime - startOfDay) / 1000;
                  const left = (startOffset / daySeconds) * 100;
                  const width = (segment.duration / daySeconds) * 100;

                  return (
                    <div
                      key={idx}
                      className={`absolute top-0 bottom-0 ${segment.color} hover:brightness-110 transition-all cursor-pointer group/segment min-w-[2px]`}
                      style={{ 
                        left: `${Math.max(0, Math.min(100, left))}%`, 
                        width: `${Math.max(0.2, Math.min(100, width))}%`
                      }}
                    >
                      {/* Tooltip */}
                      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 opacity-0 group-hover/segment:opacity-100 transition-opacity z-10 pointer-events-none whitespace-nowrap">
                        <div className={`px-3 py-2 rounded-lg shadow-xl text-xs flex flex-col items-center ${darkMode ? 'bg-slate-800 text-slate-200' : 'bg-white text-slate-800 border border-slate-100'}`}>
                          <span className="font-bold">{segment.taskTitle}</span>
                          <span className="opacity-70 text-[10px]">{segment.subtaskTitle}</span>
                          <span className={`mt-1 font-mono text-[9px] uppercase tracking-wider ${darkMode ? 'text-indigo-400' : 'text-indigo-600'}`}>
                            {formatTime(segment.startTime)} - {formatTime(segment.endTime)}
                          </span>
                        </div>
                        {/* Arrow */}
                        <div className={`w-2 h-2 rotate-45 mx-auto -mt-1 ${darkMode ? 'bg-slate-800' : 'bg-white border-r border-b border-slate-100'}`}></div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className={`text-center text-[10px] font-medium uppercase tracking-widest mt-2 ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>
              Time (24h)
            </div>
          </div>

          {/* Breakdown / Legend */}
          <div>
             <h3 className={`text-[10px] font-black uppercase tracking-[0.2em] mb-6 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>
               Activity Breakdown
             </h3>

             {taskAggregates.length > 0 ? (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {taskAggregates.map((item, idx) => (
                   <div key={idx} className={`flex items-center p-4 rounded-xl border transition-colors ${darkMode ? 'bg-slate-900/50 border-slate-800' : 'bg-slate-50 border-slate-100'}`}>
                      <div className={`w-3 h-3 rounded-full mr-3 ${item.color}`} />
                      <div className="flex-1 min-w-0">
                        <div className={`text-xs font-bold truncate ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>
                          {item.title}
                        </div>
                        <div className={`text-[10px] font-medium ${darkMode ? 'text-slate-500' : 'text-slate-500'}`}>
                          {timelineData.segments.filter(s => s.taskTitle === item.title).length} sessions
                        </div>
                      </div>
                      <div className={`text-sm font-black tabular-nums ${darkMode ? 'text-slate-200' : 'text-slate-700'}`}>
                        {formatDuration(item.duration)}
                      </div>
                   </div>
                 ))}
               </div>
             ) : (
                <div className={`py-12 flex flex-col items-center justify-center rounded-2xl border border-dashed ${darkMode ? 'bg-slate-900/30 border-slate-800' : 'bg-slate-50/50 border-slate-200'}`}>
                  <Activity size={24} className={`mb-2 opacity-20 ${darkMode ? 'text-slate-400' : 'text-slate-500'}`} />
                  <p className={`text-[10px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>
                    No activity recorded today
                  </p>
                </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AnalyticsModal;

export interface Session {
  startTime: number;
  endTime: number;
  duration: number; // in seconds
}

export interface Subtask {
  id: string;
  title: string;
  isCompleted: boolean;
  percentage?: number; // 0-100 granular progress
  timeSpent?: number; // Seconds spent on this subtask
  sessions?: Session[];
}

export interface Task {
  id: string;
  title: string;
  description: string;
  percentage: number; // 0-100
  isCompleted: boolean;
  subtasks: Subtask[];
  createdAt: number;
  totalTimeSpent?: number; // Total seconds spent on this task
}

export type SortOption = 'newest' | 'oldest' | 'progress';

export type ActivityType = 'food' | 'nap' | 'rest' | 'break' | 'drift';

export interface ActivitySession {
  id: string;
  type: ActivityType;
  startTime: number;
  endTime: number;
  duration: number;
}

import React, { useState, useEffect } from 'react';
import { Utensils, Moon, Coffee, Armchair, StopCircle } from 'lucide-react';
import { ActivityType } from '../types';

interface FloatingTimerProps {
  type: ActivityType;
  startTime: number;
  onDone: () => void;
  darkMode: boolean;
}

const FloatingTimer: React.FC<FloatingTimerProps> = ({ type, startTime, onDone, darkMode }) => {
  const [elapsed, setElapsed] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setElapsed(Math.floor((Date.now() - startTime) / 1000));
    }, 1000);
    return () => clearInterval(interval);
  }, [startTime]);

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const getConfig = () => {
    switch (type) {
      case 'food': return { icon: Utensils, label: 'Refueling', color: 'text-amber-500', bg: 'bg-amber-500' };
      case 'nap': return { icon: Moon, label: 'Power Nap', color: 'text-violet-500', bg: 'bg-violet-500' };
      case 'rest': return { icon: Armchair, label: 'Resting', color: 'text-cyan-500', bg: 'bg-cyan-500' };
      case 'break': return { icon: Coffee, label: 'Break', color: 'text-rose-500', bg: 'bg-rose-500' };
      default: return { icon: Coffee, label: 'Break', color: 'text-slate-500', bg: 'bg-slate-500' };
    }
  };

  const config = getConfig();
  const Icon = config.icon;

  return (
    <div className={`fixed bottom-6 right-6 z-40 p-4 rounded-2xl shadow-2xl border backdrop-blur-md animate-in slide-in-from-bottom-10 fade-in duration-300 flex items-center gap-4 ${
      darkMode ? 'bg-slate-900/90 border-slate-700' : 'bg-white/90 border-slate-200'
    }`}>
      <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ${config.bg} text-white`}>
        <Icon size={20} />
      </div>

      <div>
        <div className={`text-[10px] font-black uppercase tracking-widest opacity-60 ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>
          {config.label}
        </div>
        <div className={`text-xl font-light tabular-nums tracking-tight ${darkMode ? 'text-slate-100' : 'text-slate-900'}`}>
          {formatTime(elapsed)}
        </div>
      </div>

      <button 
        onClick={onDone}
        className={`ml-2 px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wider transition-all hover:scale-105 active:scale-95 ${
          darkMode 
            ? 'bg-slate-800 hover:bg-slate-700 text-white shadow-lg shadow-black/20' 
            : 'bg-slate-100 hover:bg-slate-200 text-slate-900 shadow-sm'
        }`}
      >
        Done
      </button>
    </div>
  );
};

